        def telegram_payload(self, uid=700100, name="Player @nezzxBET_bot", age=0):
            fields = {"auth_date": str(int(time.time())-age), "query_id": "test-nickname",
                      "user": json_text({"id": uid, "first_name": name})}
            check = "\n".join(f"{k}={v}" for k, v in sorted(fields.items()))
            secret = hmac.new(b"WebAppData", self.config.bot_token.encode(), hashlib.sha256).digest()
            fields["hash"] = hmac.new(secret, check.encode(), hashlib.sha256).hexdigest()
            return urllib.parse.urlencode(fields)

        def login_telegram(self, uid=700100, name="Player @nezzxBET_bot", age=0):
            signed = self.telegram_payload(uid, name, age)
            response, cookie = self.app.api("/api/auth/telegram", {"initData": signed}, {})
            return response["user"], {"Cookie": cookie.split(";", 1)[0]}, signed

