                self.assertNotIn("bombs",g)
                self.assertNotIn("seed",g)
                self.assertAlmostEqual(g["stepChance"], (5-mines)/5)
                for o in g["stages"]:
                    self.assertAlmostEqual(o["chance"]*o["multiplier"],.94)
                secret = json.loads(self.app.q("SELECT state FROM games WHERE id=?",g["id"])["state"])
                with self.assertRaises(APIError):
                    self.call("/api/tower/cashout")
                for stage in range(5):
                    cell = next(c for c in range(5) if c not in secret["bombs"][stage])
                    g = self.call("/api/tower/reveal",{"stage":stage,"index":cell})
                    with self.assertRaises(APIError):
                        self.call("/api/tower/reveal",{"stage":stage,"index":cell})
                self.assertEqual(g["status"],"won")
                self.assertEqual(verify_round(g)["bombs"],secret["bombs"])
                before = self.balance()
                with self.assertRaises(APIError):
                    self.call("/api/tower/cashout")
                self.assertEqual(self.balance(),before)

